<script module lang="ts">
/**
 * A measured value in a known range (`design/components/meter.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/meter.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { Icon, joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/meter.module.css'

export interface MeterMessages {
  /** The glyph's name past `warning`: "High". */
  warning: string
  /** The glyph's name past `danger`: "Critical". */
  danger: string
}

export interface MeterProps {
  /**
   * From this value up, the meter is in its danger band.
   */
  danger?: number
  /**
   * Required, because an unnamed meter tells a screen reader nothing.
   */
  label: string
  /**
   * The top of the range: the limit, the quota, the budget.
   */
  max?: number
  /**
   * The status glyph's names. English when omitted.
   */
  messages?: MeterMessages
  /**
   * The bottom of the range.
   */
  min?: number
  /**
   * The measured value, in the range's units. It is drawn clamped to `min`–`max`.
   */
  value: number
  /**
   * The value in the app's words, seen under the bar and heard as the meter's value.
   */
  valueText?: string
  /**
   * From this value up, the meter is in its warning band.
   */
  warning?: number
}
</script>

<script lang="ts">
let {
  danger,
  label: labelOwn,
  max = 100,
  messages = (() => ({ warning: 'High', danger: 'Critical' }))(),
  min = 0,
  value,
  valueText,
  warning,
}: MeterProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const shown = $derived(Math.min(max, Math.max(min, value)))
const ratio = $derived(max > min ? (shown - min) / (max - min) : 0)
const tone = $derived(
  danger !== undefined && value >= danger
    ? 'danger'
    : warning !== undefined && value >= warning
      ? 'warning'
      : 'accent',
)
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div class={styles.meter} data-tone={tone} data-member="meter"
    ><div
      class={styles.track}
      role="meter"
      aria-label={label}
      aria-valuenow={shown}
      aria-valuemin={min}
      aria-valuemax={max}
      aria-valuetext={valueText}
      ><div class={styles.fill} style:transform={`scaleX(${ratio})`}></div
    ></div
    >{#if tone !== 'accent' || valueText !== undefined
      }<div class={styles.readout}
        >{#if tone !== 'accent'
          }<span class={styles.status}
            ><Icon
              name={tone === 'danger' ? 'error' : 'warning'}
              size="sm"
              label={tone === 'danger' ? messages.danger : messages.warning}
          /></span
        >{/if
        }{#if valueText !== undefined
          }<span class={styles.value} aria-hidden="true">{valueText}</span
        >{/if
      }</div
    >{/if
  }</div
>{/if
}{@render joined.end?.()}
